-- VERSION-PROBE-NUMERIC-1 (2026-10-13, pillars autonomy and core; owner: "Audit and remediate all related failure modes and root causes systemwide across the
-- fleet. Merge and deploy all fixes immediately."). Second member of the stale-probe family behind the reopen churn (PROBE-SOURCE-STABILITY-1, PR 1185):
-- a probe that decides "version X is live" with LIKE / GLOB digit classes or a string >= breaks at the first two-digit minor.
--   issue-2005 (qnfo-fleet-control >= 0.4.132): live 0.26.2 matches none of '0.4.13[2-9]%', '0.4.[2-9]%', '0.[5-9].%', so the contract read
--     "pending: 0.4.132 not live yet" for 100+ runs on a closed issue that had never passed; the reopen trigger ignores pending.
--   issue-2018 (qnfo-code-orchestrator >= 0.3.17): live 0.15.1 matches none of '0.3.1[7-9]%', '0.3.[2-9]%', '0.[4-9].%'. Same state.
--   issue-2103 (idea-hub >= 1.7.0): `version >= '1.7.0'` is a string comparison, so 1.10.0 would read below 1.7.0.
-- The three probes now compare the minor and patch as integers. Issue 2005's provenance clause also counted ct_w4bx54dabidh09 (created 07:41, before the
-- 07:43:45Z deploy, refused for source qnfo-ops-deep-sweep, which is not a planner origin); it now counts only tasks created after the deploy.
-- The failure mode and its detector stop the pattern coming back (no active contract compares a version by LIKE class or string >=).
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM remediation_contracts WHERE class = 'fm-version-probe-string-compare'; DELETE FROM failure_modes WHERE fm_key = 'version-probe-string-compare'; restore the three probes from bak_20261013_version_probes (verify_probe column)
-- BACKUP: bak_20261013_version_probes

CREATE TABLE IF NOT EXISTS bak_20261013_version_probes AS SELECT class, issue_id, verify_probe, last_verdict FROM remediation_contracts WHERE class IN ('issue-2005', 'issue-2018', 'issue-2103');

UPDATE remediation_contracts SET verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM worker_live_audit WHERE worker=''qnfo-fleet-control'' AND (live_version NOT LIKE ''0.%'' OR CAST(substr(live_version, 3) AS INTEGER) > 4 OR (CAST(substr(live_version, 3) AS INTEGER) = 4 AND CAST(substr(live_version, 3 + instr(substr(live_version, 3), ''.'')) AS INTEGER) >= 132))) THEN ''pending: qnfo-fleet-control 0.4.132 not live yet ('' || COALESCE((SELECT live_version FROM worker_live_audit WHERE worker=''qnfo-fleet-control''),''?'') || '')'' WHEN EXISTS (SELECT 1 FROM code_tasks WHERE created_at > ''2026-10-06T07:44'' AND updated_at > ''2026-10-06T08:00'' AND last_error LIKE ''merge-runner:%not a trusted origin%'' AND (goal LIKE ''[issue #%'')) THEN ''fail: a planner-origin task was refused for provenance after 0.4.132'' ELSE ''ok'' END AS observed' WHERE class = 'issue-2005';
UPDATE remediation_contracts SET verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM worker_live_audit WHERE worker=''qnfo-code-orchestrator'' AND (live_version NOT LIKE ''0.%'' OR CAST(substr(live_version, 3) AS INTEGER) > 3 OR (CAST(substr(live_version, 3) AS INTEGER) = 3 AND CAST(substr(live_version, 3 + instr(substr(live_version, 3), ''.'')) AS INTEGER) >= 17))) THEN ''pending: qnfo-code-orchestrator 0.3.17 not live yet ('' || COALESCE((SELECT live_version FROM worker_live_audit WHERE worker=''qnfo-code-orchestrator''),''?'') || '')'' WHEN EXISTS (SELECT 1 FROM code_tasks WHERE created_at > ''2026-10-06T07:00'' AND status=''closed'' AND last_error LIKE ''review-rejected%'') THEN ''fail: a code task after the deploy was still review-rejected as a paraphrase'' WHEN (SELECT COUNT(*) FROM cloud_ops_events WHERE kind=''code-task.noop-refused'') = 0 THEN ''pending: no code-task.noop-refused event yet (the gate has not been exercised live)'' ELSE ''ok'' END AS observed' WHERE class = 'issue-2018';
UPDATE remediation_contracts SET verify_probe = 'SELECT ''1'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''idea-hub'' AND (CAST(version AS INTEGER) > 1 OR (CAST(version AS INTEGER) = 1 AND CAST(substr(version, 3) AS INTEGER) >= 7))) AND NOT EXISTS (SELECT 1 FROM idea_proposals WHERE (name LIKE ''owner%'' OR name LIKE ''rowan%'' OR contact = ''owner'') AND name <> ''owner-corpus'' AND status = ''triaged_hold'' AND rationale <> ''noise/question filter'' AND triaged_at >= ''2026-10-07T11:00'') AND NOT EXISTS (SELECT 1 FROM idea_proposals WHERE name = ''ask-gap'' AND rationale = ''noise/question filter'' AND triaged_at >= ''2026-10-07T11:00'') THEN ''1'' ELSE ''0'' END AS observed' WHERE class = 'issue-2103';

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, symptom, blast_radius) VALUES ('version-probe-string-compare', 'a probe decides that a worker version is live with LIKE or GLOB digit classes or a string >=, and stops matching at the first two-digit minor', '''0.[5-9].%'' matches 0.5 to 0.9 only and a string compare puts 1.10.0 below 1.7.0; qnfo-fleet-control reached 0.26 and qnfo-code-orchestrator 0.15, so contracts 2005 and 2018 read pending for 100+ runs and a closed issue never verified', 'migration 2026-10-13-version-probe-numeric: the minor and patch are compared as integers; version-pin tests already use versionAtLeast, contracts now use the same rule', 'fm-version-probe-string-compare: no active or holding contract (other than fm- detectors) compares live_version by a LIKE digit class or a version string >=', 'fm-version-probe-string-compare', '2026-10-13', 'closed issue whose contract reads pending: ... not live yet while the worker is far past that version', 'closed issues look unverified for good, and a regression in the same worker would go unseen');
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status) VALUES ('fm-version-probe-string-compare', NULL, 'FAILURE-MODE-DETECTOR-OWN-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM remediation_contracts WHERE status IN (''active'', ''holding'') AND class NOT LIKE ''fm-%'' AND (verify_probe LIKE ''%live_version LIKE ''''%[%'' OR verify_probe LIKE ''%version >= ''''%'' OR verify_probe LIKE ''%version) >= ''''%'')) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-fleet-control', 1, 'active');
